const { test } = require('node:test');
const assert = require('node:assert');
const { handle } = require('./src/app');

test('menu', () => {
  handle('POST', '/api/kitchens', { name: 'Maa', rating: 4, opened_on: '2025-01-02' });
  const r = handle('POST', '/api/menus', { kitchen_id: 1, dish: 'Rajma', price: '80', served_on: '2026-11-13' });
  assert.strictEqual(r.status, 201);
  assert.match(r.data, /80\.00/);
});

