const { test } = require('node:test');
const assert = require('node:assert');
const { handle } = require('./src/app');

test('empty date is a clear error', () => {
  handle('POST', '/api/kitchens', { name: 'Maa', rating: 4, opened_on: '2025-01-02' });
  handle('POST', '/api/menus', { kitchen_id: 1, dish: 'Rajma', price: '80', served_on: '2026-11-13' });
  assert.strictEqual(handle('POST', '/api/orders', { menu_id: 1, plates: 2, total: '160', placed_on: '' }).status, 400);
  assert.strictEqual(handle('POST', '/api/orders', { menu_id: 1, plates: 2, total: '160', placed_on: '2026-11-13' }).status, 201);
});
